function clusterNetburst = clusterNetburst(NetworkBurstPlayer, spikeTrain, BurstDetected, range, flag2, opt_clustering)
         
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% flag2                             % QC metric generated by "NetworkBurstDetection"
                                    % =0, run the clustering
                                    % =1, run the clustering
                                    % =2, the number of robustly participating neurons is low    

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%   clusterNetburst.label           % if flag2=2, =1 for primary events, =2 for secondary events

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

MIN_PRIMARY_EVENTS = 3;                         % the clustering runs when there are MORE than MIN_PRIMARY_EVENTS primary events (i.e., at least 4)
                                                % (revised October 2026: comment clarified; before, "minimum number of primary events to run the clustering")
apply_parameters('clusterNetburst');                                        % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")
K_MSEC_SEC = 1/1000;                            % factor to rescale from msec to sec

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

nNetBurst1 = NetworkBurstPlayer.nBurst;                                 % primary network burst events
nNetBurst2 = NetworkBurstPlayer.Secondary.nBurst;                       % secondary network burst events

% Clustering of network burst events            
     
if opt_clustering > 0
        
    if flag2 == 2
        fprintf("\n Clustering can not be assessed because the number of robustly participating neurons is low \n")                
        clustering = default_cluster(nNetBurst1,nNetBurst2);

%    clustering.clusteringQuality = nan;                    
%    clustering.n_cluster = 1;                
%    labels1 = ones(nNetBurst1,2);
%                    
%    if nNetBurst2 > 0
%        labels2 = ones(nNetBurst2,2);
%        labels2(:,2) = 2;
%        clustering.label = vertcat(labels1, labels2);
%    else
%        clustering.label = labels1;
%    end
    
    elseif flag2==0 || flag2==1

        % Assess the primary events
        netburst_member1 = ones(nNetBurst1,1);                   % valid primary network burst events    
        channels_part1 = NetworkBurstPlayer.Channels(:,1);       % participating primary network burst events
        NetworkBurstFeature{1} = NetworkBurstFeatures(NetworkBurstPlayer, spikeTrain, BurstDetected, range/K_MSEC_SEC, netburst_member1, channels_part1, 0, 0);

        % Assess the secondary events 
        nNetBurst2 = NetworkBurstPlayer.Secondary.nBurst;        % secondary network burst events
        if nNetBurst2 > 0
            netburst_member2 = ones(nNetBurst2,1);               % valid secondary network burst events    
            channels_part2 = NetworkBurstPlayer.Secondary.Channels(:,1);       % participating secondary network burst events
            NetworkBurstFeature{2} = NetworkBurstFeatures(NetworkBurstPlayer.Secondary, spikeTrain, BurstDetected, range/K_MSEC_SEC, netburst_member2, channels_part2, 0, 0);
        end
                    
        if nNetBurst1 > MIN_PRIMARY_EVENTS
            clustering = cluster_neuronal_events(NetworkBurstPlayer, NetworkBurstFeature, spikeTrain, range, 0);
        else
            clustering = default_cluster(nNetBurst1,nNetBurst2);

%        clustering.clusteringQuality = nan;
%        clustering.n_cluster = 1;
%        labels1 = ones(nNetBurst1,2);
%        if nNetBurst2 > 0
%            labels2 = ones(nNetBurst2,2);
%             labels2(:,2) = 2;
%                            
%             clustering.label = vertcat(labels1, labels2);
%                        
%    else
%                            
%        clustering.label = labels1;                       
%    end
%                    
        end
        
        if flag2==1
            fprintf("\n Clustering will be assessed even when the optimal bin size has not been identified \n")
    
        end
    end
else    % No clustering; single family of bursts
 
    clustering = default_cluster(nNetBurst1,nNetBurst2);
                
%    clustering.clusteringQuality = nan;
%    clustering.n_cluster = 1;
%    nNetBurst1 = NetworkBurstPlayer.nBurst;                     % primary network burst events
%    labels1 = ones(nNetBurst1,2);
%    nNetBurst2 = NetworkBurstPlayer.Secondary.nBurst;           % secondary network burst events
%    if nNetBurst2 > 0
%        labels2 = ones(nNetBurst2,2);
%        labels2(:,2) = 2;
%        clustering.label = vertcat(labels1, labels2);
%    else
%        clustering.label = labels1;
%    end
end

clusterNetburst = clustering;
end

% -------- local function --------- %            
function cluster0 = default_cluster(n1, n2)
                
    cluster0.clusteringQuality = nan;                    
    cluster0.n_cluster = 1;                
    labels1 = ones(n1,2);
                    
    if n2 > 0
        labels2 = ones(n2,2);
        labels2(:,2) = 2;
        cluster0.label = vertcat(labels1, labels2);
    else
        cluster0.label = labels1;
    end

end

